use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let hex_input = input.as_str().unwrap_or_default();
    let bytes = hex_input.chars().map(|c| c.to_digit(16).unwrap()).collect::<Vec<_>>();
    if bytes.len() % 2 != 0 {
        return serde_json::Value::Null;
    }
    let mut result = Vec::new();
    for i in 0..bytes.len() / 2 {
        let byte1 = bytes[i];
        let byte2 = bytes[i + 1];
        result.push(byte1 as i64);
        result.push(byte2 as i64);
    }
    serde_json::Value::Array(result)
}
